// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbTestCleanupTest {
	@Test
	void successfulScopeClosesExactlyOnce() {
		AtomicInteger closes = new AtomicInteger();
		try (var cleanup = LmdbTestUtil.onClose(closes::incrementAndGet)) {
			assertEquals(0, closes.get());
		}
		assertEquals(1, closes.get());
	}

	@Test
	void assertionFailureStillClosesEveryOwnerInReverseOrder() {
		List<String> closed = new ArrayList<>();
		AssertionError primary = new AssertionError("test assertion");
		RuntimeException closeFailure = new IllegalStateException("shutdown");
		AssertionError actual = assertThrows(AssertionError.class, () -> {
			try (var first = LmdbTestUtil.onClose(() -> closed.add("first"));
					var second = LmdbTestUtil.onClose(() -> {
						closed.add("second");
						throw closeFailure;
					})) {
				throw primary;
			}
		});
		assertSame(primary, actual);
		assertEquals(List.of("second", "first"), closed);
		assertArrayEquals(new Throwable[] { closeFailure }, actual.getSuppressed());
	}

	@Test
	void laterCleanupFailureIsSuppressedBehindEarlierCleanupFailure() {
		RuntimeException first = new IllegalStateException("first shutdown");
		RuntimeException second = new IllegalStateException("second shutdown");
		RuntimeException actual = assertThrows(RuntimeException.class, () -> {
			try (var outer = LmdbTestUtil.onClose(() -> {
				throw second;
			});
					var inner = LmdbTestUtil.onClose(() -> {
						throw first;
					})) {
				// Both cleanup callbacks must run even without a primary test failure.
			}
		});
		assertSame(first, actual);
		assertArrayEquals(new Throwable[] { second }, actual.getSuppressed());
	}

	@Test
	void failedTestReleasesRepositoryBeforeTemporaryDirectoryDeletion(@TempDir File directory) {
		LmdbStore store = new LmdbStore(directory);
		AssertionError expected = new AssertionError("after initialization");
		assertSame(expected, assertThrows(AssertionError.class, () -> {
			try (var cleanup = LmdbTestUtil.onClose(store::shutDown)) {
				store.init();
				throw expected;
			}
		}));
		// A new owner must be able to acquire the same directory after failure.
		LmdbStore reopened = new LmdbStore(directory);
		try (var cleanup = LmdbTestUtil.onClose(reopened::shutDown)) {
			reopened.init();
		}
		LmdbTestUtil.deleteDir(directory);
	}
}
